import { ValueParser, ValueParserResult } from "./valueparser.js";
import { ExecutionContext, Mode, Suggestion } from "./internal/parser.js";

//#region src/dependency-metadata.d.ts

/**
 * Metadata for a parser that is a dependency source.
 *
 * @internal
 * @since 1.0.0
 */
interface DependencySourceCapability {
  /** Discriminant tag. */
  readonly kind: "source";
  /** The unique dependency source identifier. */
  readonly sourceId: symbol;
  /** Metavariable used to identify this source in diagnostics. */
  readonly metavar?: string;
  /**
   * Extracts the dependency source parse result from the parser's state.
   *
   * The `state` argument is the current parser state for the source-owning
   * parser.  Each wrapper composes this method to handle its own state shape:
   * - plain source: reads from `DependencySourceState`
   * - `optional()`/`withDefault()`: unwraps `[innerState]` first
   * - `map()`: reads the pre-transform value from inner state
   *
   * Returns the `ValueParserResult` (which may be successful with any
   * value including `undefined`, or failed), a promise that resolves to the
   * same shape when extraction needs async work, or `undefined` if the state
   * does not contain a source result at all (unpopulated/wrong shape).
   * Callers and wrapper authors must handle both direct and promise-wrapped
   * results when composing `extractSourceValue`.
   */
  readonly extractSourceValue: (state: unknown) => ValueParserResult<unknown> | Promise<ValueParserResult<unknown> | undefined> | undefined;
  /**
   * When present, provides a missing-source value (e.g., from a
   * `withDefault()` wrapper).  Called during the `fillMissingSourceDefaults`
   * phase of the dependency runtime.
   */
  readonly getMissingSourceValue?: () => ValueParserResult<unknown> | Promise<ValueParserResult<unknown>>;
  /**
   * Runs the parser's effectful completion (e.g., an interactive prompt)
   * to obtain the source value when it is not extractable from state.
   *
   * Invoked only during real completion (never probes, help, or suggest),
   * serially in declaration order, at most once per parse operation—the
   * result is cached in the run-scoped effectful completion session.  Only
   * honored in asynchronous completion lanes; synchronous completion
   * ignores this hook, in which case the owning parser still completes
   * normally in the construct's final completion phase without early
   * registration.
   *
   * May resolve to `undefined` when the state offers nothing to complete.
   * A result marked `deferred` is treated the same way: it is skipped and
   * never registered.
   *
   * @since 1.3.0
   */
  readonly completeSource?: (state: unknown, exec?: ExecutionContext) => Promise<ValueParserResult<unknown> | undefined>;
  /**
   * Whether the composed {@link completeSource}, invoked on a state with
   * no parsed value, publishes a registrable result.
   *
   * A prompt wrapper without a runtime condition sets this to `true`: the
   * prompt always asks and registers its answer.  An `optional()` wrapper
   * clears it, because an absent optional occurrence declines its inner
   * completion and publishes nothing.  Scheduling barriers use this flag
   * to tell a *guaranteed* branch provider (one that publishes whenever
   * its branch runs) apart from a merely *possible* one, without running
   * any effect.
   *
   * @since 1.3.0
   */
  readonly completesWhenMissing?: boolean;
  /**
   * Whether this capability publishes whichever mutually exclusive
   * alternative the run selected, rather than an occurrence of its own.
   *
   * An `or()`/`longestMatch()` whose alternatives share one source
   * composes such a capability.  The alternative is a scope of its own,
   * so an enclosing construct's explicit source collection leaves it
   * alone unless the exclusive parser opted into collection.  Wrappers
   * compose source capabilities by spreading them, so the flag travels
   * through `optional()`, `withDefault()`, `map()`, and `multiple()`
   * without each having to forward it.
   *
   * @since 1.3.0
   */
  readonly exclusiveOccurrence?: boolean;
  /**
   * Whether the parser's output value is the actual dependency source value.
   * `false` when a transform like `map()` has been applied.
   */
  readonly preservesSourceValue: boolean;
}
/**
 * Metadata for a parser that depends on one or more dependency sources.
 *
 * @internal
 * @since 1.0.0
 */
interface DerivedDependencyCapability {
  /** Discriminant tag. */
  readonly kind: "derived";
  /** The dependency source IDs this parser depends on. */
  readonly dependencyIds: readonly symbol[];
  /** Metavariable used to identify this parser in diagnostics. */
  readonly metavar?: string;
  /**
   * Returns default values for each dependency, used when the
   * corresponding sources are not provided.
   */
  readonly getDefaultDependencyValues?: () => readonly unknown[];
  /**
   * Replays a parse with the given raw input and resolved dependency values.
   */
  readonly replayParse: (rawInput: string, dependencyValues: readonly unknown[]) => ValueParserResult<unknown> | Promise<ValueParserResult<unknown>>;
  /**
   * Replays suggestions with the given prefix and resolved dependency values.
   */
  readonly replaySuggest?: (prefix: string, dependencyValues: readonly unknown[]) => Iterable<Suggestion> | AsyncIterable<Suggestion>;
}
/**
 * Metadata for a parser whose effectful completion consumes dependency
 * source values without replaying a parse.
 *
 * A prompt with a derived configuration is the canonical case: resolving
 * the configuration reads previously published dependency values, so the
 * named sources must publish before the parser's effectful completion may
 * run.  The scheduler adds provider edges for these IDs, propagates
 * demand through them when the owning source is demanded, and includes
 * them in failure lineage.
 *
 * @internal
 * @since 1.3.0
 */
interface CompletionDependencyCapability {
  /** The dependency source IDs the effectful completion reads. */
  readonly dependencyIds: readonly symbol[];
}
/**
 * Metadata indicating that a wrapper transforms the dependency source value.
 *
 * @internal
 * @since 1.0.0
 */
interface DependencyTransformCapability {
  /** Whether the wrapper transforms the source value. */
  readonly transformsSourceValue: boolean;
}
/**
 * Composed dependency metadata for a parser node.
 *
 * A parser may have any combination of source, derived, and transform
 * capabilities.  In practice, a parser is typically either a source or
 * derived, never both.
 *
 * @internal
 * @since 1.0.0
 */
interface ParserDependencyMetadata {
  /** Present if the parser is (or wraps) a dependency source. */
  readonly source?: DependencySourceCapability;
  /** Present if the parser depends on one or more sources. */
  readonly derived?: DerivedDependencyCapability;
  /**
   * Present if the parser's effectful completion consumes dependency
   * values (e.g., a prompt with a derived configuration).
   * @since 1.3.0
   */
  readonly completion?: CompletionDependencyCapability;
  /** Present if a transform has been applied. */
  readonly transform?: DependencyTransformCapability;
}
/**
 * Extracts {@link ParserDependencyMetadata} from a value parser by reading
 * old-protocol markers (`dependencySourceMarker`, `derivedValueParserMarker`,
 * etc.).
 *
 * Returns `undefined` if the parser has no dependency-related markers.
 *
 * @param valueParser The value parser to inspect.
 * @returns Metadata, or `undefined` for plain parsers.
 * @internal
 * @since 1.0.0
 */
declare function extractDependencyMetadata<M extends Mode, T>(valueParser: ValueParser<M, T>): ParserDependencyMetadata | undefined;
/**
 * Options for `composeDependencyMetadata` when the wrapper kind is
 * `"withDefault"`.
 *
 * @internal
 * @since 1.0.0
 */
interface WithDefaultCompositionOptions {
  /** Thunk returning the default value as a `ValueParserResult`. */
  readonly defaultValue: () => ValueParserResult<unknown> | Promise<ValueParserResult<unknown>>;
}
/**
 * Composes dependency metadata through a modifier wrapper.
 *
 * - `"optional"`: composes `extractSourceValue` with array unwrapping.
 * - `"withDefault"`: adds `getMissingSourceValue` if the inner parser
 *   preserves a dependency source.
 * - `"map"`: sets `transformsSourceValue` and clears
 *   `preservesSourceValue`.
 *
 * Returns `undefined` if `inner` is `undefined`.
 *
 * @param inner The inner parser's metadata.
 * @param wrapperKind The type of modifier being applied.
 * @param options Additional options for certain wrapper kinds.
 * @returns Composed metadata, or `undefined`.
 * @internal
 * @since 1.0.0
 */
declare function composeDependencyMetadata(inner: ParserDependencyMetadata | undefined, wrapperKind: "optional" | "withDefault" | "map", options?: WithDefaultCompositionOptions): ParserDependencyMetadata | undefined;
//#endregion
export { CompletionDependencyCapability, DependencySourceCapability, DependencyTransformCapability, DerivedDependencyCapability, ParserDependencyMetadata, WithDefaultCompositionOptions, composeDependencyMetadata, extractDependencyMetadata };